u AS (
  UPDATE public."Product" p
     SET gtip1 = v.yeni, "gtip1Desc" = v.tanim, "updatedAt" = now()
    FROM v
   WHERE p.sku = v.sku AND p.gtip1 IS NOT DISTINCT FROM v.eski AND p.gtip1 IS DISTINCT FROM v.yeni
  RETURNING p.sku, v.eski, v.yeni, v.guven
)
INSERT INTO public.cfo_change_log (id, area, item, "oldValue", "newValue", source, kind, note)
SELECT gen_random_uuid()::text, 'urun', u.sku || ' GTİP', u.eski, u.yeni, 'Sistem', 'duzeltme',
       'CFO-026 GTİP yeniden sınıflandırma (güven: ' || u.guven || '); gerekçe docs/gtip/gtip-siniflandirma.json'
  FROM u;

COMMIT;

-- Doğrulama (salt-okuma)
SELECT count(*) FILTER (WHERE gtip1 ~ '^[0-9]{4}\.[0-9]{2}\.[0-9]{2}\.[0-9]{2}\.[0-9]{2}$') AS on_iki_haneli, count(*) AS maliyetli
  FROM public."Product" WHERE "unitCostTry" > 0;
SELECT count(*) FROM public.cfo_change_log WHERE item LIKE '% GTİP' AND source = 'Sistem' AND kind = 'duzeltme';
